# Read a stream of data and measure the number of valid non-comment
# lines received per second.  Can handle TICC timestamp text format
# and new binary format (12-byte fixed frames).

import sys
import time
import argparse
from collections import deque, defaultdict

try:
    import serial
except ImportError:
    print("pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)


def crc8_maxim(data: bytes) -> int:
    """Calculate CRC8-Maxim (Dallas/Maxim 1-Wire) over the given data."""
    crc = 0x00
    for byte_val in data:
        crc ^= byte_val
        for _ in range(8):
            if crc & 0x01:
                crc = (crc >> 1) ^ 0x8C
            else:
                crc >>= 1
    return crc


def is_comment_or_blank(s: str) -> bool:
    if not s:
        return True
    i = 0
    n = len(s)
    while i < n and s[i].isspace():
        i += 1
    return i >= n or s[i] == "#"


def parse_text_line(s: str):
    # Accept:
    #   "<float> <channel>"          e.g., "1.234456 chA"
    #   "<id> <value> <channel>"     e.g., "0000... 60617700 A"
    if is_comment_or_blank(s):
        return None
    parts = s.split()
    if len(parts) == 2:
        val_str, ch = parts
        try:
            float(val_str)
        except ValueError:
            return None
        return ch
    if len(parts) == 3:
        return parts[2]
    return None


def parse_minimal_marker(raw: bytes):
    # Recognize "@\r\n" as a minimal speed test marker (maps to channel '@')
    if raw == b"@\r\n":
        return '@'
    return None


def parse_new_binary_frame(frame: bytes):
    """
    Parse the new 12-byte binary format:
    - Bytes 0-1: Header (0x55, 0xAA)
    - Byte 2: Channel name (ASCII 'A' or 'B')
    - Bytes 3-6: PICstop (32-bit little-endian)
    - Bytes 7-10: TOF (32-bit little-endian)
    - Byte 11: CRC8-Maxim over bytes 2-10
    
    Returns channel character if valid, None otherwise.
    """
    if len(frame) != 12:
        return None
    
    # Check header
    if frame[0] != 0x55 or frame[1] != 0xAA:
        return None
    
    # Verify CRC over payload (bytes 2-10)
    expected_crc = crc8_maxim(frame[2:11])
    if frame[11] != expected_crc:
        return None
    
    # Extract channel name
    ch_byte = frame[2]
    if (65 <= ch_byte <= 90) or (97 <= ch_byte <= 122):
        return chr(ch_byte)
    
    return None


def normalize_channel(ch: str, normalize_ch_prefix: bool) -> str:
    # If requested, map "chA" -> "A" (case-insensitive "ch")
    if normalize_ch_prefix and len(ch) == 3 and ch[:2].lower() == "ch":
        last = ch[2:]
        if len(last) == 1 and last.isalpha():
            return last
    return ch


def drain_for_seconds(ser, seconds: float):
    if seconds <= 0:
        return
    end = time.monotonic() + seconds
    ser.reset_input_buffer()
    while time.monotonic() < end:
        _ = ser.read(4096)


def main():
    p = argparse.ArgumentParser(
        description="Measure per-channel rates from serial stream (text or binary formats)."
    )
    p.add_argument("--port", required=True, help="Serial port (e.g. COM3, /dev/ttyACM0)")
    p.add_argument("--baud", type=int, default=115200, help="Baud rate")
    p.add_argument("--window", type=float, default=5.0, help="Averaging window seconds")
    p.add_argument("--report-every", type=float, default=1.0, help="Report cadence seconds")
    p.add_argument("--timeout", type=float, default=1.0, help="Serial read timeout (s)")
    p.add_argument("--encoding", default="utf-8", help="Text encoding")
    p.add_argument("--debug-drop", type=int, default=0, help="Print up to N dropped frames after start")
    p.add_argument("--warmup", type=float, default=None,
                   help="Seconds to suppress printing after stream becomes active "
                        "(default: 2×window; use 0 to disable)")
    p.add_argument("--flush-seconds", type=float, default=1.0,
                   help="Seconds to actively drain/discard input after opening port (default: 1.0)")
    # Active stream detection
    p.add_argument("--active-window", type=float, default=1.0,
                   help="Seconds used to detect active stream (default: 1.0)")
    p.add_argument("--min-events-total", type=int, default=150,
                   help="Total lines within active-window to mark stream active (default: 150)")
    # Channel handling
    p.add_argument("--channels", nargs="+", default=["A"],
                   help="Allowed channel labels after normalization (default: A). "
                        "Example: --channels chA or --normalize-ch-prefix --channels A. "
                        "Use '@' to measure minimal marker format.")
    p.add_argument("--normalize-ch-prefix", action="store_true",
                   help="Normalize 'chX' -> 'X' for text lines")
    # Binary format handling
    p.add_argument("--binary-mode", choices=["auto", "new"], default="auto",
                   help="Binary format mode: 'auto' (detect), 'new' (12-byte fixed frames). "
                        "Default: auto")
    args = p.parse_args()

    allowed_channels = set(args.channels)
    warmup = 2.0 * args.window if args.warmup is None else max(0.0, args.warmup)

    try:
        ser = serial.Serial(
            port=args.port,
            baudrate=args.baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=args.timeout,
        )
    except serial.SerialException as e:
        print(f"Failed to open {args.port}: {e}", file=sys.stderr)
        sys.exit(2)

    print(f"Opened {args.port} @ {args.baud} baud. Averaging window: {args.window}s")
    print(f"Binary mode: {args.binary_mode}")
    if args.flush_seconds > 0:
        print(f"Draining input for {args.flush_seconds:.2f}s to avoid stale buffered data...")
    drain_for_seconds(ser, args.flush_seconds)
    ser.reset_input_buffer()
    print("Waiting for data (text or binary format)...")

    stamps = defaultdict(deque)   # ch -> deque[float]
    known_channels = set()

    total_counts = defaultdict(int)
    run_start = None

    stream_seen = False
    active_seen = False
    t_first_data = 0.0
    next_report = 0.0
    dropped_preview = 0
    first_print_done = False

    recent_events = deque()
    
    # Auto-detection state for binary mode
    binary_mode_detected = None  # None = not yet determined, "new", or "text"
    sync_buffer = bytearray()  # Buffer for finding 0x55 0xAA sync pattern

    def prune_window(now):
        cutoff = now - args.window
        for ch in list(known_channels):
            dq = stamps[ch]
            while dq and dq[0] < cutoff:
                dq.popleft()

    def compute_window(now):
        prune_window(now)
        counts = {ch: len(stamps[ch]) for ch in stamps.keys()}
        if not active_seen:
            return {}, {}, 0.0, 0.0
        elapsed = now - run_start
        duration = args.window if elapsed >= args.window else max(elapsed, 1e-6)
        rates = {ch: counts.get(ch, 0) / duration for ch in counts.keys()}
        return rates, counts, duration, elapsed

    def update_active(now):
        nonlocal active_seen, run_start, next_report
        cutoff = now - args.active_window
        while recent_events and recent_events[0] < cutoff:
            recent_events.popleft()
        if not active_seen and len(recent_events) >= args.min_events_total:
            active_seen = True
            run_start = now
            next_report = run_start + args.report_every
            print("Active measurement stream detected. Whole-run averaging starts now.")
            if warmup > 0:
                print(f"Warming up for {warmup:.2f}s before first on-screen report...")

    try:
        while True:
            ch = None
            raw = None
            
            # Determine which mode to use for parsing
            if args.binary_mode == "new" or (args.binary_mode == "auto" and binary_mode_detected == "new"):
                # New binary mode: 12-byte fixed frames with 0x55 0xAA header
                # Keep reading bytes until we find sync pattern or have a frame
                while len(sync_buffer) < 12:
                    byte_data = ser.read(1)
                    if not byte_data:
                        break
                    sync_buffer.append(byte_data[0])
                    
                    # Look for sync pattern 0x55 0xAA at start
                    if len(sync_buffer) >= 2:
                        # If we don't have sync at start, keep looking
                        while len(sync_buffer) >= 2 and not (sync_buffer[0] == 0x55 and sync_buffer[1] == 0xAA):
                            sync_buffer.pop(0)
                
                if len(sync_buffer) >= 12:
                    frame = bytes(sync_buffer[:12])
                    sync_buffer = sync_buffer[12:]  # Remove processed frame
                    raw = frame
                    ch = parse_new_binary_frame(frame)
                    
                    if ch is not None and args.binary_mode == "auto" and binary_mode_detected is None:
                        binary_mode_detected = "new"
                        print("Auto-detected: new binary format (12-byte frames)")
                else:
                    continue
                    
            elif binary_mode_detected == "text" or binary_mode_detected == "minimal":
                # Text or minimal marker mode: CRLF-terminated
                raw = ser.read_until(b"\r\n")
                if not raw:
                    continue
                
                # Decode and try text formats
                content = raw[:-2] if raw.endswith(b"\r\n") else raw.rstrip(b"\r\n")
                text = content.decode(args.encoding, errors="ignore")
                ch = parse_text_line(text)
                
                # Try minimal marker (@\r\n) if text parsing failed
                if ch is None:
                    ch = parse_minimal_marker(raw)
                    
            else:  # args.binary_mode == "auto" and no detection yet
                # Auto-detect: try to peek ahead for sync pattern
                peek_data = ser.read(12)
                if not peek_data:
                    continue
                
                # Check if it looks like new binary format
                if len(peek_data) >= 12 and peek_data[0] == 0x55 and peek_data[1] == 0xAA:
                    # Looks like new binary, add to sync buffer and process
                    sync_buffer.extend(peek_data)
                    continue  # Loop back to process as new binary
                else:
                    # Not new binary, treat as CRLF-terminated text
                    # Put data back by searching for CRLF
                    sync_buffer.extend(peek_data)
                    crlf_idx = bytes(sync_buffer).find(b"\r\n")
                    if crlf_idx >= 0:
                        raw = bytes(sync_buffer[:crlf_idx+2])
                        sync_buffer = sync_buffer[crlf_idx+2:]
                        
                        content = raw[:-2] if raw.endswith(b"\r\n") else raw.rstrip(b"\r\n")
                        text = content.decode(args.encoding, errors="ignore")
                        ch = parse_text_line(text)
                        
                        # Try minimal marker (@\r\n) if text parsing failed
                        if ch is None:
                            ch = parse_minimal_marker(raw)
                            if ch is not None:
                                binary_mode_detected = "minimal"
                                print("Auto-detected: minimal marker format (@)")
                        
                        # If we got a valid channel from text parsing, we've detected text format
                        if ch is not None and binary_mode_detected is None:
                            binary_mode_detected = "text"
                            print("Auto-detected: text format")
                    else:
                        continue  # Need more data to find CRLF

            # Normalize and apply whitelist
            if ch is not None:
                ch = normalize_channel(ch, args.normalize_ch_prefix)
                if ch not in allowed_channels:
                    ch = None

            if ch is not None:
                now = time.monotonic()
                if not stream_seen:
                    stream_seen = True
                    t_first_data = now
                    print("First valid data frame received.")

                # Record timestamp
                stamps[ch].append(now)

                # Active detection and counts
                recent_events.append(now)
                update_active(now)
                if active_seen:
                    total_counts[ch] += 1
                    known_channels.add(ch)
            else:
                if stream_seen and args.debug_drop and dropped_preview < args.debug_drop and raw is not None:
                    tail = raw[-12:] if len(raw) >= 12 else raw
                    hex_tail = tail.hex(" ")
                    ascii_tail = "".join(chr(b) if 32 <= b <= 126 else "." for b in tail)
                    print(
                        f"[drop] len={len(raw)} "
                        f"tail_hex={hex_tail} tail_ascii={ascii_tail!r}"
                    )
                    dropped_preview += 1

            if active_seen:
                now = time.monotonic()
                if now >= next_report:
                    intervals = int((now - next_report) // args.report_every) + 1
                    next_report += intervals * args.report_every

                    rates, counts, duration, elapsed = compute_window(now)

                    # First print gate: warmup elapsed and at least one event in window
                    if not first_print_done:
                        if elapsed < warmup:
                            continue
                        if sum(counts.values()) == 0:
                            continue
                        first_print_done = True

                    # Only print channels present in this window
                    ch_list = sorted([c for c, cnt in counts.items() if cnt > 0])
                    if not ch_list:
                        continue

                    print(
                        " | ".join(
                            f"{c}: {rates.get(c, 0.0):.2f} Hz "
                            f"(count={counts.get(c, 0)} over {duration:.2f}s)"
                            for c in ch_list
                        )
                    )

    except KeyboardInterrupt:
        print("\nExiting...")
        try:
            now = time.monotonic()
            rates, counts, duration, elapsed = compute_window(now)

            if active_seen and run_start is not None:
                run_seconds = max(1e-6, now - run_start)
                ch_list = sorted([c for c, tot in total_counts.items() if tot > 0])
                if ch_list:
                    print("Final whole-run averages (from active stream start):")
                    for c in ch_list:
                        avg_hz = total_counts[c] / run_seconds
                        print(f"  {c}: {avg_hz:.4f} Hz over {run_seconds:.2f}s (total={total_counts[c]})")
                else:
                    print("No channel events recorded during active run.")
            elif stream_seen:
                print("Data lines were seen, but the stream never reached the active threshold.")
            else:
                print("No data lines received.")

            window_chs = sorted([c for c, cnt in counts.items() if cnt > 0])
            if window_chs:
                print("Last window snapshot:")
                print(
                    " | ".join(
                        f"{c}: {rates.get(c, 0.0):.2f} Hz "
                        f"(count={counts.get(c, 0)} over {duration:.2f}s)"
                        for c in window_chs
                    )
                )
        finally:
            try:
                ser.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()
